# Keep archive listings (tag / category / year pages generated by
# jekyll-archives-v2) out of sitemap.xml. They are thin lists of links and
# are also marked noindex in _includes/seo_alternates.liquid.
#
# Runs after jekyll-archives-v2 (normal priority) and before jekyll-sitemap
# (lowest priority).
module ArchiveSitemapExclude
  class Generator < Jekyll::Generator
    safe true
    priority :low

    def generate(site)
      site.pages.each do |page|
        archive = page.data["layout"] == "archive" ||
                  page.class.name.to_s.include?("Archive") ||
                  page.url.include?("/tag/") ||
                  page.url.include?("/category/")
        page.data["sitemap"] = false if archive
      end
    end
  end
end
